.pv-custom-header{display:block;break-inside:avoid;page-break-inside:avoid;margin:0 0 2mm;font-family:Arial,sans-serif}
.pv-header-official{display:grid;align-items:start;text-align:center;gap:3mm;font-family:'Times New Roman',serif;font-size:7px;line-height:1.15}
.pv-header-official>div{min-width:0}.pv-header-isabee-official,.pv-header-poly-official,.pv-header-ndere-official{grid-template-columns:1fr 19mm 1fr}
.pv-header-esstic-official{grid-template-columns:1fr 1fr}
.pv-header-center-logo{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;text-align:center;font-size:6px;line-height:1.1}
.pv-header-center-logo img{display:block;max-width:17mm;max-height:17mm;object-fit:contain;margin:0 auto 1mm}
.pv-header-brand{display:grid;grid-template-columns:18% 64% 18%;align-items:center;gap:2mm;text-align:center;margin:2mm 2% 1mm;font-size:7px;line-height:1.15}
.pv-header-logo{display:flex;justify-content:center;align-items:center;min-width:0}
.pv-header-logo img,.pv-header-side-logos img{display:block;max-width:17mm;max-height:17mm;object-fit:contain;margin:auto}
.pv-header-school{font-weight:bold}.pv-header-school strong{font-size:12px}
.pv-header-school span{font-size:7px}
.pv-header-ndere-school{text-align:center;font-size:7px;line-height:1.15;margin:1mm 0}
.pv-header-ndere-school strong{font-size:12px}
.pv-header-side-logos{display:flex;justify-content:space-between;align-items:center;margin:1mm 8%;height:13mm}
.pv-header-side-logos span{display:block;width:20mm}
.pv-header-rule{height:2px;margin:1mm 0}
.pv-header-rule-red{border-top:2px solid #c90018;border-bottom:1px solid #c90018}
.pv-header-document-title h2{text-align:center;font-size:10px;margin:1mm 0}
.pv-header-document-title .context{font-size:7px;line-height:1.25;margin:1mm 0 2mm}
.paper-a3 .pv-header-official{font-size:9px}.paper-a3 .pv-header-center-logo{font-size:7px}.paper-a3 .pv-header-brand,.paper-a3 .pv-header-ndere-school{font-size:9px}
.paper-a3 .pv-header-school strong,.paper-a3 .pv-header-ndere-school strong{font-size:15px}.paper-a3 .pv-header-document-title h2{font-size:12px}.paper-a3 .pv-header-document-title .context{font-size:9px}
@media print{.pv-custom-header{break-inside:avoid;page-break-inside:avoid}.pv-header-document-title{break-after:avoid;page-break-after:avoid}}
